        JsonWriter jsonWriter = jsonTreeWriter.endObject();
        assertThat(jsonTreeWriter.peek(), is((JsonElement) new JsonObject()));
        assertThat(jsonWriter, is(jsonTreeWriter));
    }

    @Test
    public void testName() throws IOException {
        String name = "test";
        JsonWriter jsonWriter = jsonTreeWriter.name(name);
        assertThat(jsonTreeWriter.pendingName, is(name));
        assertThat(jsonWriter, is(jsonTreeWriter));
    }

    @Test
    public void testNullValue() throws IOException {
        JsonWriter jsonWriter = jsonTreeWriter.nullValue();
        assertThat(jsonTreeWriter.get(), is((JsonElement) JsonNull.INSTANCE));
        assertThat(jsonWriter, is(jsonTreeWriter));
    }

    @Test
    public void testValue_Boolean() throws IOException {
        boolean value = true;
        JsonWriter jsonWriter = jsonTreeWriter.value(value);
        assertThat(jsonTreeWriter.get(), is((JsonElement) new JsonPrimitive(value)));
        assertThat(jsonWriter, is(jsonTreeWriter));
    }

